.version 7.0
.target sm_80
.address_size 64

.visible .entry relu_fp16(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 N
)
{
    // registers
    .reg .pred   %p<2>;
    .reg .u32    %r<5>;
    .reg .u64    %rd<4>;
    .reg .f16    %f<2>;

    // load parameters
    ld.param.u64    %rd1, [input_ptr];
    ld.param.u64    %rd2, [output_ptr];
    ld.param.u32    %r4,  [N];

    // thread index = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %r1, %ctaid.x;
    mul.lo.u32 %r1, %r1, %ntid.x;
    add.u32 %r1, %r1, %tid.x;          // %r1 = global linear index

    // if (idx >= N) return;
    setp.ge.u32 %p1, %r1, %r4;
    @%p1 bra DONE;

    // byte offset = idx * sizeof(half) = idx * 2
    cvt.u64.u32 %rd3, %r1;
    mul.wide.u32 %rd3, %r1, 2;

    // load half
    add.u64 %rd3, %rd1, %rd3;
    ld.global.nc.f16 %f1, [%rd3];

    // ReLU: max(val, 0)
    mov.f16 %f2, 0F0000;               // half 0.0
    max.f16 %f1, %f1, %f2;

    // store result
    add.u64 %rd3, %rd2, %rd3;
    st.global.f16 [%rd3], %f1;

DONE:
    ret;
}
'''

